'use strict';
// paced-seam — the one-in-flight LLM advice seam.
//
// Source provenance: ported from SuperInstance/pong-quilt core.js makeSeam
// (Rounds 3+4), where tests/seam.test.js pins the same contract inside the
// game. This module is the standalone extraction: zero dependencies, no DOM,
// no fetch — you bring the transport, the seam owns the contract.
//
// The contract (each clause is FAIL-first pinned in test/seam.test.js):
//   1. PACING: at most one fire per minIntervalMs (measured on the injected
//      clock — the seam never trusts wall time it wasn't given).
//   2. SERIALIZATION: at most one request in flight; a second fire() is
//      REFUSED (returns null), never queued. Queues hide latency; refusals
//      surface it.
//   3. STALE FENCE: a delivered result is applied only if it is the latest
//      seq. Out-of-order arrivals die on the fence, counted in dropped.stale.
//      (Under serialization stale stays 0 — the pin PROVES it rather than
//      assuming it, so a future "optimization" that loosens pacing trips the
//      fence loudly instead of corrupting state silently.)
//   4. TIMEOUT (opt-in): timeoutMs races the transport. Whichever settles
//      first owns the result — exactly-once settlement, the late arrival is
//      fenced by `settled`, NOT double-counted as stale. A hung endpoint
//      frees the seam, counts the death in dropped.timedOut, and reports an
//      error through onResult. timeoutMs=0 arms no timer (the pinned
//      pre-timeout behavior — opt-in, not a silent semantic change).
//   5. HONEST COUNTERS: every refusal/death class is counted on the
//      `dropped` object the caller must surface in the UI. Drops are counted,
//      not hidden.
//
// Usage:
//   const { makeSeam } = require("paced-seam");
//   const seam = makeSeam({
//     minIntervalMs: 2000,          // fire on death/interval, never per frame
//     timeoutMs: 8000,              // optional; 0 = no timer
//     transport: (payload) =>      // YOUR endpoint; the seam owns pacing only
//       fetch(endpoint, { method: "POST", body: JSON.stringify(payload) })
//         .then((r) => r.json()),
//     onResult: (res, seq, err) => { // err != null on transport failure/timeout
//       if (err) return showSeamError(err);
//       applyAdvice(res);            // res is always the LATEST request's reply
//     },
//   });
//   // in your loop, on death or interval:
//   seam.fire(buildPayload());       // -> seq number, or null (refused, counted)
//   // in your UI:
//   seam.dropped // { inFlight, paced, stale, timedOut } — render these

function makeSeam(opts) {
  const transport = opts.transport, minIntervalMs = opts.minIntervalMs || 0;
  const timeoutMs = opts.timeoutMs || 0;
  const schedule = opts.schedule || ((fn, ms) => setTimeout(fn, ms));
  const cancel = opts.cancel || ((h) => clearTimeout(h));
  const now = opts.now || (() => Date.now());
  const onResult = opts.onResult || (() => {});
  let inFlight = false, lastFire = -Infinity, seq = 0;
  const dropped = { inFlight: 0, paced: 0, stale: 0, timedOut: 0 };
  // Stale-drop fence: while fire() refuses during in-flight, a delivered
  // response is always the latest seq — but if a future caller loosens
  // pacing, out-of-order arrivals die here, silently-safe. Fences outrank
  // gates; the counter proves the fence stands (test/seam.test.js).
  return {
    fire(payload) { // returns the request's seq, or null if refused (counted)
      const t = now();
      if (inFlight) { dropped.inFlight++; return null; }
      if (t - lastFire < minIntervalMs) { dropped.paced++; return null; }
      const mySeq = ++seq; lastFire = t; inFlight = true;
      let settled = false, timer = null;
      // Exactly-once settlement shared by the timeout race and the transport:
      // whichever lands first owns the result; the late arrival dies on the
      // `settled` fence. (A post-timeout transport arrival does NOT count
      // stale — the timeout already owned and counted that request.)
      const settle = (res, err) => {
        if (settled) return; settled = true;
        if (timer !== null) { cancel(timer); timer = null; }
        inFlight = false;
        if (mySeq !== seq) { dropped.stale++; return; }
        onResult(res, mySeq, err);
      };
      if (timeoutMs > 0) timer = schedule(() => {
        dropped.timedOut++;
        settle(null, new Error("seam timeout after " + timeoutMs + "ms"));
      }, timeoutMs);
      Promise.resolve().then(() => transport(payload)).then(
        (res) => settle(res),
        (err) => settle(null, err));
      return mySeq;
    },
    get inFlight() { return inFlight; },
    get lastSeq() { return seq; },
    dropped: dropped, // honest counters — the UI surfaces these
  };
}

module.exports = { makeSeam };

