'use strict';
// Pins for the paced-seam contract. FAIL-first: every pin below is RED when
// src/seam.js is absent or the contract regresses. Source provenance:
// ported from SuperInstance/pong-quilt core.js makeSeam (Rounds 3+4), pinned
// there by tests/seam.test.js. This suite re-pins the contract standalone so
// adopters get the same guarantees without the game.
const test = require("node:test");
const assert = require("node:assert/strict");
const { makeSeam } = require("../src/seam.js");

const tick = () => new Promise((r) => setImmediate(r)); // flush the microtask queue

test("paces requests: at most one per minIntervalMs", async () => {
  let t = 1000;
  let calls = 0;
  const seam = makeSeam({ transport: () => { calls++; return Promise.resolve({ move: 1 }); },
    minIntervalMs: 200, now: () => t, onResult: () => {} });
  assert.equal(seam.fire({}), 1);       // t=1000
  await tick();                          // let the first request settle — inFlight false
  t = 1100; assert.equal(seam.fire({}), null); // 100ms later — refused on PACING, not in-flight
  await tick();
  t = 1200; assert.equal(seam.fire({}), 2);    // 200ms later — allowed
  await tick();
  assert.equal(calls, 2);
  assert.equal(seam.dropped.paced, 1);
  assert.equal(seam.dropped.inFlight, 0); // the refusal above was pacing, serialized separately
});

test("serializes in-flight: a second fire during a pending request is refused", async () => {
  let t = 0;
  let calls = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const seam = makeSeam({ transport: () => { calls++; return gate.then(() => ({ move: -1 })); },
    minIntervalMs: 0, now: () => t, onResult: () => {} });
  assert.equal(seam.fire({}), 1);
  assert.equal(seam.inFlight, true);
  assert.equal(seam.fire({}), null); // in flight — serialized, not queued
  assert.equal(seam.dropped.inFlight, 1);
  release(); await tick();
  assert.equal(seam.inFlight, false);
  assert.equal(calls, 1); // exactly one network touch for two fires
});

test("delivered results arrive in strict fire order (monotonic seq)", async () => {
  let t = 0;
  const delivered = [];
  const seam = makeSeam({ transport: (p) => Promise.resolve({ move: p.move }),
    minIntervalMs: 10, now: () => t, onResult: (res, seq) => delivered.push({ res, seq }) });
  for (let i = 0; i < 5; i++) { t += 10; seam.fire({ move: i }); await tick(); }
  assert.deepEqual(delivered.map((d) => d.seq), [1, 2, 3, 4, 5]);
  assert.deepEqual(delivered.map((d) => d.res.move), [0, 1, 2, 3, 4]);
});

test("stale fence stands: counters are honest and delivery guards on latest seq", async () => {
  let t = 0;
  const delivered = [];
  const seam = makeSeam({ transport: () => Promise.resolve({ move: 0 }),
    minIntervalMs: 0, now: () => t, onResult: (res, seq) => delivered.push(seq) });
  seam.fire({}); await tick();
  seam.fire({}); await tick();
  assert.deepEqual(delivered, [1, 2]); // latest-seq guard: only fresh results deliver
  assert.equal(seam.dropped.stale, 0); // with serialization, stale stays 0 — and PROVEN, not assumed
  assert.equal(seam.lastSeq, 2);
});

test("transport rejection resolves through onResult as an error, not a hang", async () => {
  let t = 0;
  const errs = [];
  const seam = makeSeam({ transport: () => Promise.reject(new Error("endpoint down")),
    minIntervalMs: 0, now: () => t,
    onResult: (res, seq, err) => { if (err) errs.push(err.message); } });
  seam.fire({}); await tick();
  assert.deepEqual(errs, ["endpoint down"]);
  assert.equal(seam.inFlight, false); // failure frees the seam — no stuck lock
});

test("timeout frees the seam: hung transport counts timedOut, errors out, next fire allowed", async () => {
  let t = 0;
  const errs = [];
  let calls = 0;
  const seam = makeSeam({
    transport: () => { calls++; return new Promise(() => {}); }, // never resolves — the hung endpoint
    minIntervalMs: 0, timeoutMs: 25, now: () => t,
    onResult: (res, seq, err) => { if (err) errs.push(err.message); } });
  assert.equal(seam.fire({}), 1);
  assert.equal(seam.inFlight, true);
  assert.equal(seam.fire({}), null); // still in flight — refused, counted
  await new Promise((r) => setTimeout(r, 80)); // let the 25ms timeout fire
  assert.equal(seam.inFlight, false, "timeout freed the seam");
  assert.equal(seam.dropped.timedOut, 1, "the death is counted, not hidden");
  assert.equal(seam.dropped.inFlight, 1);
  assert.equal(seam.dropped.stale, 0, "the late transport arrival is fenced by settle(), not double-counted");
  assert.equal(errs.length, 1);
  assert.match(errs[0], /seam timeout after 25ms/);
  t += 1;
  assert.equal(seam.fire({}), 2, "the seam lives again after a timeout");
  await new Promise((r) => setTimeout(r, 80)); // second hung request also times out
  assert.equal(calls, 2);
  assert.equal(seam.dropped.timedOut, 2);
});

test("fast resolution cancels the timer: no timeout counted, normal delivery", async () => {
  let t = 0;
  const scheduled = [], cancelled = [];
  let fakeTimer = 0;
  const delivered = [];
  const seam = makeSeam({
    transport: () => Promise.resolve({ move: -1 }),
    minIntervalMs: 0, timeoutMs: 1000, now: () => t,
    schedule: (fn, ms) => { const h = ++fakeTimer; scheduled.push({ h, ms }); return h; },
    cancel: (h) => cancelled.push(h),
    onResult: (res, seq) => delivered.push(res) });
  seam.fire({}); await tick();
  assert.deepEqual(scheduled.map((s) => s.ms), [1000], "timer armed");
  assert.deepEqual(cancelled, scheduled.map((s) => s.h), "timer cancelled on fast delivery");
  assert.deepEqual(delivered, [{ move: -1 }]);
  assert.equal(seam.dropped.timedOut, 0);
  assert.equal(seam.inFlight, false);
});

// --- Pins beyond the source suite: contract sharp edges an adopter WILL hit ---

test("exactly-once settlement: a transport that resolves AND its timeout race count one death", async () => {
  let t = 0;
  let resolveLate;
  const errs = [];
  const seam = makeSeam({
    transport: () => new Promise((r) => { resolveLate = r; }),
    minIntervalMs: 0, timeoutMs: 20, now: () => t,
    onResult: (res, seq, err) => { if (err) errs.push(err.message); } });
  seam.fire({});
  await new Promise((r) => setTimeout(r, 60));        // timeout owns the settle
  resolveLate({ move: 1 }); await tick();              // late arrival dies on the fence
  assert.equal(seam.dropped.timedOut, 1);
  assert.equal(seam.dropped.stale, 0, "post-timeout arrival is NOT stale — the timeout already owned it");
  assert.equal(errs.length, 1);                        // onResult fired exactly once
  assert.equal(seam.inFlight, false);
});

test("fire() return contract: seq number on accept, null on every refusal class", async () => {
  let t = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const seam = makeSeam({ transport: () => gate, minIntervalMs: 100, now: () => t,
    onResult: () => {} });
  assert.equal(seam.fire({}), 1);            // accepted → seq
  assert.equal(seam.fire({}), null);         // in-flight → null
  t = 50;                                     // still in flight anyway
  assert.equal(seam.fire({}), null);         // still null
  release(); await tick();
  t = 99; assert.equal(seam.fire({}), null); // paced refusal → null (99-0 < 100)
  assert.equal(seam.dropped.paced, 1);
  t = 100; assert.equal(seam.fire({}), 2);   // boundary: exactly minIntervalMs → allowed
  release && (release = null);
  await tick();
});

test("drop counters are the UI's honest surface: all four classes independently countable", async () => {
  let t = 0;
  const seam = makeSeam({ transport: () => Promise.resolve({}), minIntervalMs: 5, now: () => t,
    onResult: () => {} });
  // paced
  seam.fire({}); await tick();
  t = 2; seam.fire({});                       // paced refusal
  // inFlight
  t = 10; seam.fire({});                       // accepted
  t = 11; seam.fire({});                       // in-flight refusal
  await tick();
  assert.deepEqual({ ...seam.dropped }, { inFlight: 1, paced: 1, stale: 0, timedOut: 0 });
  assert.equal(seam.lastSeq, 2);
});

test("timeout is opt-in: timeoutMs=0 (default) arms no timer — pinned R3 behavior, not a silent semantic change", async () => {
  let t = 0;
  let scheduled = 0;
  const seam = makeSeam({ transport: () => new Promise(() => {}),
    minIntervalMs: 0, now: () => t,
    schedule: () => { scheduled++; return ++scheduled; },
    cancel: () => {},
    onResult: () => {} });
  seam.fire({});
  assert.equal(scheduled, 0, "no timer without opt-in timeoutMs");
  assert.equal(seam.dropped.timedOut, 0);
});

test("injectable clock/scheduler make the seam fully deterministic under test (no real timers needed except the two timeout integration pins)", () => {
  // Guard pin: the constructor accepts now/schedule/cancel overrides.
  // (The two timeout integration pins above use real 20-25ms timers on
  // purpose — timeout behavior must be proven against REAL timer interleaving,
  // not only against the fake scheduler.)
  const seam = makeSeam({ transport: () => Promise.resolve(1), minIntervalMs: 0,
    now: () => 42, schedule: (fn) => 7, cancel: () => {}, onResult: () => {} });
  assert.equal(seam.fire({}), 1);
  return tick();
});
